Let $(Z_1,\dots ,Z_q)$ be a regular $q$-tuple i.e.  $Z_i^{n-1}\neq 0$ for some $i$. Then
\begin{enumerate}
\item any $Z_j$ is a polynomial in $Z_i$, and;
 \item if $(\rho, V)$ is the corresponding  representation, then  there is a $k$-algebra isomorphism $\rho(\Aqn)\simeq k[z]/z^nk[z].$
 \end{enumerate}

The exact sequences (\ref{fues}) and (\ref{stes}) with the section $\chi$ induce isomorphisms of varieties:
\begin{align*}
\GAqnk&\simeq \GL_q(k)\times \mathcal{I}_{q,n} \\
 G_1\simeq &P_1\times (\mathcal{I}_{q,n}\cap G_1)
\end{align*}
Moreover:
\begin{enumerate}
  \item The groups $\mathcal{I}_{q,n}$ and $\mathcal{I}_{q,n}\cap G_1$  are unipotent. Let $\mathcal{I}^j_{q,n}$ denote the subgroup of $\mathcal{I}_{q,n}$ consisting of elements which reduce to the identity modulo $\mathfrak{m}^{j+2}.$ Each of these groups is normal in $\GAqnk$
  \item There is  an isomorphism of additive group schemes $\mathcal{I}^j_{q,n}/\mathcal{I}^{j+1}_{q,n}\simeq (\mathfrak{m}^{j+2}/\mathfrak{m}^{j+3})^q$.
  \item There are natural isomorphisms of varieties:
  \begin{align}
     \mathcal{I}_{q,n}\simeq &(\mathfrak{m}^2)^{(q)} \\ \mathcal{I}_{q,n}\cap G_1 &\simeq \mathfrak{m}^2\times (\mathfrak{q}_1\mathfrak{m})^{(q-1)}\end{align} The exponents in parentheses represent iterated Cartesian products.
     \item The groups $\GAqnk$ and $G_1$ are connected affine group schemes.
\end{enumerate}
